package models

import (
	"sort"
	"time"
)

// KEVType represents the source of KEV information
type KEVType string

const (
	// CISAKEVType is for CISA KEV data
	CISAKEVType KEVType = "cisa"
	// VulnCheckKEVType is for VulnCheck KEV data
	VulnCheckKEVType KEVType = "vulncheck"
)

// VulnCheckXDB holds VulnCheck database details
type VulnCheckXDB struct {
	XDBID       string    `json:"xdbID"`
	XDBURL      string    `json:"xdbURL"`
	DateAdded   time.Time `json:"dateAdded"`
	ExploitType string    `json:"exploitType"`
	CloneSSHURL string    `json:"cloneSSHURL"`
}

// VulnCheckReportedExploitation captures reported exploitation data
type VulnCheckReportedExploitation struct {
	URL       string    `json:"url"`
	DateAdded time.Time `json:"dateAdded"`
}

// VulnCheckKEV stores VulnCheck-specific KEV information
type VulnCheckKEV struct {
	XDB                    []VulnCheckXDB                `json:"xdb,omitempty"`
	ReportedExploitation   []VulnCheckReportedExploitation `json:"reportedExploitation,omitempty"`
}

// CISAKEV stores CISA-specific KEV information
type CISAKEV struct {
	Note string `json:"note,omitempty"`
}

// KEV stores information about Known Exploited Vulnerabilities
type KEV struct {
	Type                     KEVType       `json:"type"`
	VendorProject            string        `json:"vendorProject"`
	Product                  string        `json:"product"`
	VulnerabilityName        string        `json:"vulnerabilityName"`
	ShortDescription         string        `json:"shortDescription"`
	RequiredAction           string        `json:"requiredAction"`
	KnownRansomwareCampaignUse string `json:"knownRansomwareCampaignUse"`
	DateAdded                time.Time     `json:"dateAdded"`
	DueDate                  *time.Time    `json:"dueDate,omitempty"`
	CISA                     *CISAKEV      `json:"cisa,omitempty"`
	VulnCheck                *VulnCheckKEV `json:"vulncheck,omitempty"`
}

// SortForJSONOutput sorts KEVs by Type and then VulnerabilityName
func SortForJSONOutput(kevs []KEV) []KEV {
	sort.Slice(kevs, func(i, j int) bool {
		if kevs[i].Type != kevs[j].Type {
			return kevs[i].Type < kevs[j].Type
		}
		return kevs[i].VulnerabilityName < kevs[j].VulnerabilityName
	})
	return kevs
}
EOF

